export const IndiaMap = ({
  statesData = [],
  selectedState = null,
  onSelectState,
  activeMode = 'ALLOCATION',
}) => {
  const [hoveredState, setHoveredState] = useState(null);

  // Map state data by name or code
  const getStateInfo = (code, name) => {
    if (!statesData || !statesData.length) return null;
    const normName = (name || '').toLowerCase().replace(/[^a-z]/g, '');
    return statesData.find((s) => {
      if (s.state_code === code) return true;
      const sNorm = (s.state_name || '').toLowerCase().replace(/[^a-z]/g, '');
      if (sNorm === normName) return true;
      if ((normName.includes('pondi') || normName.includes('puduch')) && (sNorm.includes('pondi') || sNorm.includes('puduch'))) return true;
      if (normName === 'jammuandkashmir' && (sNorm.includes('jammu') || sNorm.includes('ladakh'))) return true;
      if (normName === 'ladakh' && (sNorm.includes('ladakh') || sNorm.includes('jammu'))) return true;
      if (normName === 'arunachalpradesh' && sNorm.includes('arunachal')) return true;
      if ((normName.includes('daman') || normName.includes('dadra')) && (sNorm.includes('daman') || sNorm.includes('dadra'))) return true;
      return sNorm.includes(normName) || normName.includes(sNorm);
    });
  };

  // ── MODE COLOUR SYSTEM ──────────────────────────────────────────────────────
  // Each mode returns [fill, opacity] based on real enriched data values.

  const modeColors = {
    ALLOCATION: {
      // Tiers by total_allocation_inr (INR)
      tiers: [
        { threshold: 2e9,  color: '#0d4429' }, // >200Cr — deepest
        { threshold: 5e8,  color: '#065f46' }, // >50Cr
        { threshold: 1e8,  color: '#047857' }, // >10Cr
        { threshold: 1e7,  color: '#10b981' }, // >1Cr
      ],
      field: 'total_allocation_inr',
      base: '#1e293b',
    },
    ACTIVITY: {
      // Tiers by recommended_works_count (MPLADS works)
      tiers: [
        { threshold: 3000, color: '#1e1b4b' },
        { threshold: 1500, color: '#3730a3' },
        { threshold: 800,  color: '#4f46e5' },
        { threshold: 200,  color: '#818cf8' },
      ],
      field: 'recommended_works_count',
      base: '#1e293b',
    },
    COMPLETION: {
      // Tiers by completed_works_count (cyan/teal spectrum)
      tiers: [
        { threshold: 1200, color: '#083344' },
        { threshold: 600,  color: '#0e7490' },
        { threshold: 250,  color: '#06b6d4' },
        { threshold: 50,   color: '#22d3ee' },
      ],
      field: 'completed_works_count',
      base: '#0f172a',
    },
    RISK: {
      // Tiers by risk_count (red/crimson spectrum)
      tiers: [
        { threshold: 60, color: '#7f1d1d' },
        { threshold: 30, color: '#991b1b' },
        { threshold: 12, color: '#dc2626' },
        { threshold: 4,  color: '#f87171' },
      ],
      field: 'risk_count',
      base: '#1e293b',
    },
  };

  const getFillColor = (stateItem) => {
    const info = getStateInfo(stateItem.code, stateItem.name);
    if (!info) return '#1e293b';

    const mode = modeColors[activeMode] || modeColors.ALLOCATION;
    const value = info[mode.field] || 0;

    for (const tier of mode.tiers) {
      if (value >= tier.threshold) return tier.color;
    }
    return mode.base;
  };

  // ── TOOLTIP DATA ─────────────────────────────────────────────────────────────
  const getTooltipLines = (info) => {
    if (!info) return ['LGD Administrative Territory'];
    const lines = [`${info.district_count} Districts`];
    if (activeMode === 'ALLOCATION') {
      const amt = info.total_allocation_inr;
      if (amt) {
        const formatted = amt >= 1e7 ? `₹${(amt / 1e7).toFixed(2)} Cr` : `₹${(amt / 1e5).toFixed(2)} Lakh`;
        lines.push(`Allocation: ${formatted}`);
      }
      if (info.recommended_works_count) lines.push(`${info.recommended_works_count.toLocaleString('en-IN')} Works`);
    } else if (activeMode === 'ACTIVITY') {
      if (info.recommended_works_count) lines.push(`${info.recommended_works_count.toLocaleString('en-IN')} Active Works`);
    } else if (activeMode === 'COMPLETION') {
      if (info.completed_works_count) lines.push(`${info.completed_works_count.toLocaleString('en-IN')} Completed`);
      if (info.recommended_works_count) {
        const rate = Math.round((info.completed_works_count || 0) / (info.recommended_works_count || 1) * 100);
        lines.push(`${rate}% Completion Rate`);
      }
    } else if (activeMode === 'RISK') {
      if (info.risk_count != null) lines.push(`${info.risk_count} High/Critical Signals`);
    }
    return lines;
  };

  const tooltipColor = { ALLOCATION: 'text-emerald-400', ACTIVITY: 'text-indigo-400', COMPLETION: 'text-teal-400', RISK: 'text-rose-400' };

  return (
    <div className="relative w-full h-full flex flex-col items-center justify-center p-2 select-none">
      {/* Floating Analytical State Tooltip */}
      {hoveredState && (() => {
        const info = getStateInfo(hoveredState.code, hoveredState.name);
        const lines = getTooltipLines(info);
        return (
          <div className="absolute top-2 left-2 z-30 pointer-events-none px-4 py-2.5 rounded-xl bg-slate-950/95 border border-amber-500/30 text-xs shadow-2xl backdrop-blur-md space-y-1 min-w-[180px]">
            <div className="flex items-center justify-between">
              <span className="font-extrabold text-slate-100 font-sans">{hoveredState.name}</span>
              <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-300 font-bold border border-amber-500/30">
                {hoveredState.code}
              </span>
            </div>
            {lines.map((line, i) => (
              <div key={i} className={`text-[11px] font-sans ${i === 0 ? 'text-slate-400' : tooltipColor[activeMode] || 'text-amber-400 font-bold'}`}>
                {line}
              </div>
            ))}
            <div className="text-[10px] text-amber-300/80 font-sans font-semibold pt-1 border-t border-slate-800 flex items-center justify-between">
              <span>STATE → DISTRICTS → WORKS</span>
              <span>Click →</span>
            </div>
          </div>
        );
      })()}

      {/* Selected State Badge Notification */}
      {selectedState && (
        <div className="absolute top-2 right-2 z-20 px-3 py-1.5 rounded-lg bg-amber-500/10 border border-amber-500/30 text-xs font-sans text-amber-300 flex items-center gap-2 shadow-lg backdrop-blur-md">
          <span className="w-2 h-2 rounded-full bg-amber-400 animate-pulse" />
          <span>Selected: <strong>{selectedState.state_name}</strong></span>
        </div>
      )}

      {/* Interactive GeoJSON SVG Map */}
      <svg
        viewBox="0 0 650 700"
        className="w-full min-h-[320px] sm:min-h-[440px] max-h-[580px] object-contain drop-shadow-2xl transition-all duration-300"
      >
        <g stroke="#090d16" strokeWidth="1.2" strokeLinejoin="round" strokeLinecap="round">
          {DETAILED_INDIA_STATES.map((s) => {
            const info = getStateInfo(s.code, s.name);
            const isSelected =
              selectedState?.state_code === info?.state_code ||
              selectedState?.state_name === info?.state_name ||
              selectedState?.state_code === s.code ||
              selectedState?.state_name === s.name;
            const isHovered = hoveredState?.code === s.code;

            return (
              <motion.path
                key={s.code}
                d={s.path}
                fill={getFillColor(s)}
                stroke={isSelected ? '#f59e0b' : isHovered ? '#60a5fa' : '#0f172a'}
                strokeWidth={isSelected ? 2.8 : isHovered ? 2.0 : 1.2}
                initial={{ opacity: 0.9 }}
                whileHover={{ scale: 1.018, opacity: 1 }}
                transition={{ duration: 0.15 }}
                className={`cursor-pointer transition-colors duration-150 ${isSelected ? 'drop-shadow-[0_0_10px_rgba(245,158,11,0.5)]' : ''}`}
                onMouseEnter={() => setHoveredState(s)}
                onMouseLeave={() => setHoveredState(null)}
                onTouchStart={() => setHoveredState(s)}
                onClick={() => {
                  const targetInfo = info || { state_code: s.code, state_name: s.name, district_count: 1 };
                  if (onSelectState) {
                    onSelectState(targetInfo);
                  }
                }}
              >
                <title>{s.name}</title>
              </motion.path>
            );
          })}
        </g>
      </svg>
    </div>
  );
};

export default IndiaMap;
